 def __init__(self):
  super().__init__(convert_charrefs=True);self.parts=[];self.current=''
 def flush(self):
  if self.current.strip():self.parts.append(self.current.strip())
  self.current=''
 def handle_starttag(self,t,a):
  if t in ('p','br'):self.flush()
 def handle_endtag(self,t):
  if t=='p':self.flush()
